import type { OpenWrtSettings, RuleSetManifestEntry } from "./types";

type Json = Record<string, unknown>;

/**
 * Localize all remote rule-sets generated by upstream into `type: "local"` entries pointing to
 * `settings.paths.ruleSetDir`, and return the manifest of files to download/maintain on OpenWrt.
 *
 * Also cleans up the now-unused `rule-set-download` http_client and `route.default_http_client`.
 */
export function adaptRuleSets(config: Json, settings: OpenWrtSettings): RuleSetManifestEntry[] {
  const manifest: RuleSetManifestEntry[] = [];
  const route = config.route as { rule_set?: Json[]; default_http_client?: unknown } | undefined;
  if (!route || !Array.isArray(route.rule_set)) return manifest;

  const baseDir = settings.paths.ruleSetDir.trim().replace(/\/+$/, "");
  const overrides = settings.paths.ruleSetUrlOverrides ?? {};

  route.rule_set = route.rule_set.map((rs) => {
    if (rs.type !== "remote") return rs;

    const tag = String(rs.tag);
    const defaultUrl = String(rs.url ?? "");
    const customUrl = typeof overrides[tag] === "string" ? overrides[tag].trim() : "";
    const url = customUrl || defaultUrl;
    const format: "binary" | "source" = rs.format === "source" ? "source" : "binary";
    const ext = format === "source" ? "json" : "srs";
    const localPath = `${baseDir}/${tag}.${ext}`;

    manifest.push({ tag, url, format, path: localPath });

    return {
      type: "local",
      tag,
      format,
      path: localPath,
    };
  });

  // Remove the upstream `rule-set-download` HTTP client when no remote rule-sets remain.
  const hasRemote = route.rule_set.some((rs) => rs.type === "remote");
  if (!hasRemote) {
    if (route.default_http_client === "rule-set-download") {
      delete route.default_http_client;
    }
    if (Array.isArray(config.http_clients)) {
      const remaining = (config.http_clients as Json[]).filter((c) => c.tag !== "rule-set-download");
      if (remaining.length > 0) {
        config.http_clients = remaining;
      } else {
        delete config.http_clients;
      }
    }
  }

  return manifest;
}
